mapper.select:
select t1.*
from TBL_CEA_QUALITY_ASSESSMENT t1
left join TBL_ORGANIZATION t2 on t2.ORGID = t1.FILLBELONGGROUP
where (t1.creator = #{param.creator}

   or t1.creator in (SELECT DISTINCT STAFFID FROM TBL_USER_ORGRELATION WHERE DEPTID IN (${param.getDeptIds}))
)

    AND t1.state = #{param.state}


    AND t2.ORGNAME like concat('%',concat(#{param.fillBelongGroupName},'%'))

order by t1.id desc
